contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry: send an arbitrary amount to c.play
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract can send the requested amount
        require(address(this).balance >= amount);

        // observe pot before the call and c's balance before
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balCBefore = address(c).balance;

        bool reverted;
        // perform the call and record whether it reverted
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe pot after the call and c's balance after
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balCAfter = address(c).balance;

        // General rule: if the call did not revert, then potAfter is either potBefore + amount
        // (the ticket was simply added) or 0 (the contract paid out and reset pot).
        // We express this invariant without using any contract internals other than the public getter pot().
        assert(reverted || potAfter == potBefore + amount || potAfter == 0);
    }

    receive() external payable {}
}

